"""Chapter 2: Molecular Representations (50 multiple choice, 50 free response)."""
from qb import *


def build(b):
    # ------------------------------------------------------------ 2.1 Molecular representations
    b.mc('2.1', 1, 'A partially condensed structure is CH₃CH₂CH₂OH. What is its molecular formula?', 'C₃H₈O', ['C₃H₆O', 'C₃H₇O', 'C₃H₈O₂'],
         'Count the carbons (3), the hydrogens (3 + 2 + 2 + 1 = 8) and the oxygen (1).')
    b.mc('2.1', 2, 'Which statement about molecular formulas is correct?', 'A molecular formula does not show how the atoms are connected, so C₄H₁₀O fits several different compounds',
         ['A molecular formula shows which atoms are bonded to each other', 'Every molecular formula corresponds to exactly one compound', 'A molecular formula shows the lone pairs on each atom'],
         'The molecular formula gives only the number of each kind of atom. Constitutional isomers share a formula.')
    b.mc('2.1', 2, 'Which bond-line structure is the same compound as the condensed structure (CH₃)₂CHCH₂CH₃?', 'CC(C)CC', ['CCCCC', 'CC(C)(C)C', 'CC(C)CCC'],
         '(CH₃)₂CH- is a carbon with two methyl groups; attached to CH₂CH₃ it gives 2-methylbutane.', oimg=True)
    b.fr('2.1', 1, 'Write the molecular formula for CH₃CH₂COCH₃.', 'C₄H₈O', 'Four carbons, 3 + 2 + 0 + 3 = 8 hydrogens, one oxygen.')
    b.fr('2.1', 2, 'Draw the complete Lewis structure of CH₃OCH₃ (dimethyl ether), showing every lone pair. How many lone pairs are there in total?',
         'Two lone pairs, both on the oxygen atom.', 'Each carbon has four bonds and no lone pairs. Oxygen forms two bonds and keeps two lone pairs.', aimg=S('C[O:1]C', lone=[1]))
    b.fr('2.1', 2, 'Give two different compounds with the molecular formula C₂H₆O as condensed structures.', 'CH₃CH₂OH (ethanol) and CH₃OCH₃ (dimethyl ether).',
         'They are constitutional isomers: the same formula with different connectivity.', aimg=S('CCO', 'COC'))
    b.fr('2.1', 3, 'The bond-line structure of 2-methylbutane is shown. Write its partially condensed structure and its molecular formula.', 'CH₃CH(CH₃)CH₂CH₃ (or (CH₃)₂CHCH₂CH₃); C₅H₁₂.',
         'Each vertex and line end is a carbon. The branch point carbon bears one hydrogen; the CH₂ has two and each CH₃ has three: 3 + 1 + 3 + 2 + 3 = 12.', img=S('CC(C)CC'))
    # ------------------------------------------------------------ 2.2 Bond-line structures
    b.mc('2.2', 1, 'How many carbon atoms are in the compound shown?', '7', ['6', '8', '9'], 'Count each vertex and line end: the chain has 6 carbons plus one methyl branch.', img=S('CCCCC(C)C'))
    assert formula('CC(C)CC(=O)O') == 'C5H10O2'
    b.mc('2.2', 2, 'What is the molecular formula of the compound shown?', 'C₅H₁₀O₂', ['C₅H₁₂O₂', 'C₅H₈O₂', 'C₄H₈O₂'],
         'Five carbons; the CH₃, CH₃, CH, CH₂ carbons carry 3 + 3 + 1 + 2 = 9 hydrogens, plus the acid O-H = 10.', img=S('CC(C)CC(=O)O'))
    b.mc('2.2', 2, 'Which statement about bond-line structures is correct?', 'Carbon atoms are at each bend and line end, and hydrogen atoms bonded to carbon are not drawn',
         ['Every hydrogen atom must be drawn', 'Carbon atoms are written as the letter C', 'Lone pairs on oxygen must always be drawn'],
         'Bond-line structures omit carbon labels and C-H hydrogens; each carbon is assumed to have enough hydrogens for four bonds.')
    b.mc('2.2', 2, 'How many hydrogen atoms are bonded to the carbon that bears the OH group?', '1', ['0', '2', '3'],
         'That carbon has bonds to OH, CH₃ and CH₂ (three bonds), so one hydrogen completes four bonds.', img=S('CC(O)CC'))
    assert formula('CC(C)CC(C)=O') == 'C6H12O'
    b.mc('2.2', 3, 'Which compound has the molecular formula C₆H₁₂O?', 'CC(C)CC(C)=O', ['CC(C)CCC(C)=O', 'CCCCCCO', 'CC(=O)CCC(=O)C'],
         'Only 4-methyl-2-pentanone gives six carbons and twelve hydrogens with one oxygen (the others are C₇H₁₄O, C₆H₁₄O and C₆H₁₀O₂).', oimg=True)
    b.fr('2.2', 1, 'Draw the bond-line structure of (CH₃)₂CHCH₂CH₃.', 'The bond-line structure is a four-carbon chain with a methyl branch on the second carbon (2-methylbutane).',
         'Each vertex is a carbon; the CH branch carries one methyl group.', aimg=S('CC(C)CC'))
    b.fr('2.2', 2, 'Draw the bond-line structure of CH₃CH₂CH(OH)CH₃.', 'A four-carbon chain with an OH group on carbon 2 (2-butanol).', 'Draw the zigzag chain and attach OH to the second carbon.', aimg=S('CCC(C)O'))
    b.fr('2.2', 2, 'What is the molecular formula of the compound shown?', 'C₇H₁₄O', 'Seven carbons; hydrogens: 3 + 3 + 3 + 0 + 2 + 3 = 14 (the quaternary carbon has none); one oxygen.', img=S('CC(C)(C)CC(C)=O'))
    b.fr('2.2', 3, 'Draw bond-line structures of all constitutional isomers of C₄H₁₀.', 'Two isomers: butane (an unbranched chain) and 2-methylpropane (isobutane).', 'Only these two carbon skeletons are possible with four carbons.', aimg=S('CCCC', 'CC(C)C', labels='I II'))
    b.fr('2.2', 3, 'For the compound shown, give the molecular formula and identify the carbon atom that bears no hydrogen atoms.', 'C₅H₁₀O₂; the carbonyl (C=O) carbon has no hydrogens.',
         'Carbon atoms: CH₃ (3), CH₂ (2), C=O (0), O-CH₂ (2), CH₃ (3): ten hydrogens in total.', img=S('CCC(=O)OCC'))
    # ------------------------------------------------------------ 2.3 Functional groups
    b.mc('2.3', 1, 'Which functional group is present in this compound?', 'An alcohol', ['An ether', 'An aldehyde', 'An amine'], 'The OH group on a carbon atom is an alcohol.', img=S('CCO'))
    b.mc('2.3', 1, 'Which functional group is present in this compound?', 'A ketone', ['An aldehyde', 'An ester', 'A carboxylic acid'], 'A carbonyl group bonded to two carbons is a ketone.', img=S('CC(=O)C'))
    b.mc('2.3', 2, 'Which functional group is present in this compound?', 'An ester', ['A carboxylic acid', 'An ether', 'A ketone'], 'C(=O)-O-C: a carbonyl carbon bonded to an OR group.', img=S('CC(=O)OC'))
    b.mc('2.3', 2, 'Which functional group is present in this compound?', 'A nitrile', ['An alkyne', 'An amine', 'An imine'], 'The C≡N group is a nitrile.', img=S('CC#N'))
    b.mc('2.3', 2, 'Which functional group is present in this compound?', 'An amide', ['An ester', 'An amine', 'A nitrile'], 'A carbonyl group bonded directly to nitrogen is an amide.', img=S('CC(=O)NC'))
    b.mc('2.3', 3, 'Which pair of functional groups (besides the aromatic ring) is present in aspirin?', 'An ester and a carboxylic acid', ['A ketone and a carboxylic acid', 'An ester and an aldehyde', 'An ether and a carboxylic acid'],
         'The acetyl group is attached through oxygen (an ester), and the other substituent is CO₂H.', img=S('CC(=O)Oc1ccccc1C(=O)O'))
    b.fr('2.3', 1, 'Name the functional group in CH₃CH₂CHO.', 'An aldehyde.', 'A carbonyl group with at least one hydrogen attached to the carbonyl carbon.')
    b.fr('2.3', 2, 'Identify the functional group and classify it as primary, secondary or tertiary.', 'An amine; it is primary because nitrogen is bonded to one carbon.', 'Count the carbon atoms bonded to nitrogen: one.', img=S('CC(C)N'))
    b.fr('2.3', 2, 'Identify the two functional groups in this compound.', 'An alkene (C=C) and an alcohol (OH).', 'The C=C is an alkene; the OH on an sp³ carbon is an alcohol.', img=S('C=CCO'))
    b.fr('2.3', 3, 'Identify the two carbonyl-containing functional groups in this compound.', 'A carboxylic acid and an amide.', 'CO₂H is a carboxylic acid; C(=O)N is an amide.', img=S('O=C(O)CCC(=O)N'))
    b.fr('2.3', 3, 'Draw one aldehyde and one ketone, each with the molecular formula C₃H₆O.', 'Propanal (CH₃CH₂CHO) is the aldehyde and acetone (CH₃COCH₃) is the ketone.', 'Both are constitutional isomers with the carbonyl group in different positions.', aimg=S('CCC=O', 'CC(C)=O', labels='aldehyde ketone'))
    b.fr('2.3', 3, 'Is the compound shown an amine or an amide? Explain.', 'It is an amide, because nitrogen is bonded directly to the carbonyl carbon.', 'An amine has nitrogen bonded only to carbon and hydrogen atoms that are not part of a carbonyl group.', img=S('CN(C)C(C)=O'))
    # ------------------------------------------------------------ 2.4 Carbon atoms with formal charges
    b.mc('2.4', 1, 'A carbon atom with a positive formal charge and no lone pair (a carbocation) has how many bonds?', '3', ['2', '4', '1'], 'It has only six valence electrons around it: three bonds.')
    b.mc('2.4', 2, 'A carbon atom has three bonds and one lone pair. What is its formal charge?', 'Negative (-1)', ['Positive (+1)', 'Neutral', '-2'], 'Three bonds plus a lone pair gives five valence electrons, one more than neutral carbon.')
    b.mc('2.4', 2, 'Which structure contains a carbocation?', 'C[CH+]C', ['C[CH-]C', 'CC(C)O', 'C=C(C)C'], 'Only the first has a carbon with three bonds and no lone pair (positive charge).', oimg=True)
    b.mc('2.4', 3, 'How many hydrogen atoms are bonded to the charged carbon in this ion?', '0', ['1', '2', '3'], 'The charged carbon is bonded to three methyl groups and a lone pair, so it has no hydrogens.', img=S('C[C-](C)C'))
    b.fr('2.4', 1, 'Draw the methyl cation. How many bonds and lone pairs does the carbon have?', 'Three bonds and no lone pairs; formal charge +1.', 'A carbocation carbon has three bonds and an empty p orbital.')
    b.fr('2.4', 2, 'A carbon atom with three bonds can be either positive or negative. How can you tell which?', 'Count the lone pairs: three bonds and no lone pair is positive (+1); three bonds and one lone pair is negative (-1).', 'Formal charge depends on the electrons assigned to the carbon.')
    b.fr('2.4', 3, 'State the formal charge on the terminal CH₂ carbon of this ion and the number of lone pairs on it.', 'Negative (-1) with one lone pair.', 'It has three bonds (two to H, one to C) and a lone pair.', img=S('C=C[CH2-]'))
    # ------------------------------------------------------------ 2.5 Lone pairs
    b.mc('2.5', 1, 'How many lone pairs are on the oxygen atom of an alcohol (R-OH)?', '2', ['0', '1', '3'], 'Oxygen has six valence electrons: two shared in bonds and four as two lone pairs.')
    b.mc('2.5', 2, 'How many lone pairs does the nitrogen atom of a neutral amine (R₃N) have?', '1', ['0', '2', '3'], 'Nitrogen has five valence electrons: three form bonds and two remain as one lone pair.')
    b.mc('2.5', 2, 'Which atom in this compound has two lone pairs?', 'The oxygen', ['The nitrogen', 'The carbonyl carbon', 'Both the oxygen and the nitrogen'], 'The carbonyl oxygen has two lone pairs; the nitrogen has one.', img=S('CC(=O)N'))
    b.mc('2.5', 3, 'How many lone pairs are on all the atoms of acetic acid, CH₃CO₂H?', '4', ['2', '3', '6'], 'The carbonyl oxygen has two lone pairs and the hydroxyl oxygen has two.', img=S('CC(=O)O'))
    b.fr('2.5', 1, 'How many lone pairs does the chlorine atom in CH₃Cl have?', 'Three.', 'Chlorine has seven valence electrons: one forms the bond and six form three lone pairs.')
    b.fr('2.5', 2, 'Redraw the compound showing all lone pairs. How many are there?', 'Two lone pairs, both on the oxygen.', 'Ether oxygen forms two bonds and keeps two lone pairs.', img=S('COC'), aimg=S('C[O:1]C', lone=[1]))
    b.fr('2.5', 3, 'How many lone pairs are on all the heteroatoms of the compound shown?', 'Four: two on the carbonyl oxygen and two on the other oxygen.', 'Each neutral oxygen with two bonds (or a double bond) has two lone pairs.', img=S('CC(=O)OC'))
    b.fr('2.5', 3, 'Lone pairs are usually not drawn in bond-line structures. Why is it still important to recognize them?', 'Lone pairs make atoms basic and nucleophilic and take part in resonance, so they must be known when predicting reactivity.', 'They determine how the molecule reacts even when not drawn.')
    # ------------------------------------------------------------ 2.6 Three-dimensional bond-line structures
    b.mc('2.6', 1, 'In a bond-line drawing, what does a dashed bond indicate?', 'The group is behind the plane of the page', ['The group is in front of the plane of the page', 'The bond is a double bond', 'The bond is very weak'], 'A dash points away from the viewer.')
    b.mc('2.6', 1, 'In a bond-line drawing, what does a solid wedge indicate?', 'The group is in front of the plane of the page', ['The group is behind the plane of the page', 'The bond is a triple bond', 'The group is lone-pair bearing'], 'A wedge points toward the viewer.')
    b.mc('2.6', 3, 'A tetrahedral carbon is drawn with two bonds in the plane, one on a wedge and one on a dash. Where are the groups on the wedge and the dash?', 'The wedge group points toward the viewer and the dash group points away', ['Both point toward the viewer', 'Both point away from the viewer', 'Both lie in the plane of the page'], 'Wedge: toward; dash: away; two plain bonds lie in the plane of the page.')
    g, kind = wedge_text('C[C@H](O)CC')
    b.mc('2.6', 2, f'In the drawing shown, {g} is drawn on a {kind}. Where is that group relative to the plane of the page?', 'Toward the viewer (in front of the page)', ['Behind the page', 'In the plane of the page', 'It cannot be determined'], 'A solid wedge means toward the viewer.', img=S('C[C@H](O)CC'))
    b.fr('2.6', 1, 'What do a plain bond, a solid wedge and a dashed bond mean in a three-dimensional bond-line structure?', 'A plain bond lies in the plane of the page, a wedge comes toward the viewer, and a dash goes away from the viewer.', 'These three bond types let a flat drawing show tetrahedral geometry.')
    g2, kind2 = wedge_text('C[C@@H](Cl)CC')
    b.fr('2.6', 2, f'Describe the position of {g2} in the drawing shown, relative to the plane of the page.', f'It is drawn on a {kind2}, so it points {"toward the viewer" if kind2 == "wedge" else "away from the viewer"}.', 'Wedge means toward and dash means away from the viewer.', img=S('C[C@@H](Cl)CC'))
    b.fr('2.6', 3, 'One student draws CH₃CH(OH)CH₂CH₃ with the OH group on a wedge; another draws it on a dash. Are these the same molecule? Explain.', 'No. They are mirror images that cannot be superimposed (enantiomers).', 'Swapping the wedge and dash at the only stereocenter gives the mirror-image arrangement.', img=S('C[C@H](O)CC', 'C[C@@H](O)CC', labels='I II'))
    b.fr('2.6', 1, 'Name two drawing styles other than wedge-and-dash that show three-dimensional structure.', 'Fischer projections and Haworth projections.', 'Both are covered in Section 2.6 of the text.')
    # ------------------------------------------------------------ 2.7 Introduction to resonance
    b.mc('2.7', 1, 'Which arrow is placed between resonance structures?', 'A double-headed arrow (↔)', ['An equilibrium arrow (⇌)', 'A single reaction arrow (→)', 'A curved arrow'], 'Resonance structures are connected by a double-headed straight arrow and enclosed in brackets.')
    b.mc('2.7', 2, 'Which statement about a resonance hybrid is correct?', 'It is a single species that is a combination of all the resonance structures', ['The molecule rapidly flips between the resonance structures', 'Only the most stable resonance structure actually exists', 'Each resonance structure is a separate isomer'],
         'Resonance structures are drawing tools; the real molecule is one hybrid.')
    b.mc('2.7', 3, 'Why is a single bond-line structure inadequate for acetate, CH₃CO₂⁻?', 'It shows one C=O and one C-O⁻ bond, but the two carbon-oxygen bonds are actually equivalent', ['It does not show the carbon atoms', 'It shows too many hydrogens', 'It places the negative charge on carbon'],
         'The charge and double bond are delocalized over both oxygens, so resonance is needed.', img=S('CC(=O)[O-]'))
    b.fr('2.7', 1, 'What do the brackets and the double-headed arrow mean when they surround a set of structures?', 'The structures are resonance structures of one species, not different molecules in equilibrium.', 'The double-headed arrow is reserved for resonance.')
    b.fr('2.7', 2, 'Is resonance an equilibrium between the resonance structures? Explain.', 'No. The molecule is a single hybrid; resonance structures do not interconvert.', 'Equilibrium involves different species converting; resonance describes one species.')
    b.fr('2.7', 2, 'Define resonance stabilization.', 'The lowering of energy that comes from delocalizing electrons over more than one atom through resonance.', 'Delocalized electrons are more stable than localized ones.')
    # ------------------------------------------------------------ 2.8 Curved arrows
    b.mc('2.8', 1, 'In resonance structures, curved arrows show the movement of what?', 'A pair of electrons', ['An atom', 'A proton', 'A positive charge only'], 'Each curved arrow shows the movement of one electron pair.')
    b.mc('2.8', 2, 'Where should the tail of a curved arrow start?', 'On a lone pair or a π bond', ['On the nucleus of an atom', 'On a formal charge', 'On any hydrogen atom'], 'The tail marks the source electrons.')
    b.mc('2.8', 2, 'Which is NOT allowed when drawing resonance arrows?', 'Breaking a single bond', ['Moving a lone pair to form a π bond', 'Moving a π bond onto an adjacent atom', 'Moving a π bond to become a lone pair'], 'Resonance moves lone pairs and π bonds, never σ bonds, and never exceeds an octet for second-row elements.')
    ac = 'C[C:1](=[O:2])[O-:3]'
    good = [('lpa', 3, 315), ('bond', 1, 3), {'bend': .35}], [('bond', 1, 2), ('atom', 2), {'bend': .7, 'e_off': 12}]
    arrows = lambda *p: [(a[0], a[1], a[2]) for a in p]
    b.mc('2.8', 3, 'Which set of curved arrows correctly converts this resonance structure of acetate into the other one?',
         A(ac, arrows(*good), lone=[2]), [A(ac, arrows(good[0]), lone=[2]), A(ac, arrows(good[0], [('bond', 1, 2), ('atom', 1), {'bend': -.6}]), lone=[2]),
                                           A(ac, arrows([('bond', 1, 3), ('atom', 3), {'bend': .5, 'e_off': -10}], [('lpa', 2, 270), ('bond', 1, 2), {'bend': -.6}]), lone=[2])],
         'Arrow 1 moves a lone pair of O⁻ to form the C=O π bond; arrow 2 moves the old π bond onto the other oxygen as a lone pair.', oimg=True)
    b.fr('2.8', 2, 'Draw curved arrow(s) to convert the allyl cation resonance structure shown into the other one.', 'One curved arrow from the C=C π bond to the space between the C⁺ and its neighbouring carbon, forming a new π bond and moving the positive charge.',
         'The π bond moves toward the cation, forming a new π bond and leaving a cation at the other end.', img=S('[CH2:1]=[CH:2][CH2+:3]'), aimg=A('[CH2:1]=[CH:2][CH2+:3]', [(('bond', 1, 2), ('bond', 2, 3), {'bend': .8, 's_off': 6})]))
    b.fr('2.8', 2, 'Why can a curved arrow not be drawn starting from a single bond in resonance?', 'Resonance moves only π bonds and lone pairs. Breaking a single (σ) bond would change the connectivity of the atoms, which is not resonance.', 'Resonance structures differ only in electron positions, not atom positions.')
    b.fr('2.8', 3, 'How many curved arrows are needed to convert one resonance structure of acetate into the other? Describe where each starts and ends.', 'Two: a lone pair on the O⁻ forms a C=O π bond, and the original C=O π bond becomes a lone pair on the other oxygen.', 'One arrow forms a new π bond and the other pushes the old π bond onto oxygen.',
         img=S('CC(=O)[O-]'), aimg=A(ac, arrows(*good), lone=[2]))
    b.fr('2.8', 3, 'A curved arrow starts on the π bond of a C=O group and points to oxygen. Describe the resulting structure.', 'Oxygen gains a lone pair (becoming O⁻) and the carbon loses the π bond (becoming C⁺).', 'The two π electrons move onto the more electronegative oxygen.')
    # ------------------------------------------------------------ 2.9 Formal charges in resonance structures
    b.mc('2.9', 1, 'What is the formal charge on the oxygen atom that has one single bond and three lone pairs?', '-1', ['0', '+1', '-2'], 'Six valence electrons minus seven assigned electrons gives -1.')
    b.mc('2.9', 2, 'What is the formal charge on nitrogen in the ammonium ion, NH₄⁺?', '+1', ['0', '-1', '+4'], 'Four bonds and no lone pair gives five minus four electrons: +1.')
    b.mc('2.9', 3, 'The ion CH₂=CH-O⁻ has a second resonance structure. On which atom is the negative charge in it?', 'The terminal carbon', ['The oxygen', 'The middle carbon', 'Neither; the second structure is neutral'], 'The oxygen lone pair forms a C=O bond and the C=C π electrons end up as a lone pair on the terminal carbon.', img=S('C=C[O-]'))
    b.fr('2.9', 1, 'What is the formal charge on an oxygen atom that has three bonds and one lone pair?', '+1', 'Six valence electrons minus (2 + 3) = +1, as in H₃O⁺.')
    b.fr('2.9', 2, 'Draw the second resonance structure of the ion shown, including formal charges.', 'The negative charge moves to the terminal carbon: ⁻CH₂-CH=O.', 'Use two curved arrows: a lone pair from O forms C=O and the C=C π bond moves to carbon.', img=S('C=C[O-]'), aimg=S('C=C[O-]', '@↔', '[CH2-]C=O'))
    b.fr('2.9', 2, 'Must the total charge be the same in every resonance structure of an ion? Explain.', 'Yes. Resonance only moves electrons, so the overall charge is unchanged; the individual formal charges may move.', 'Electrons are moved, not added or removed.')
    # ------------------------------------------------------------ 2.10 Drawing resonance structures
    b.mc('2.10', 2, 'Which of these is NOT one of the five patterns used to find resonance structures?', 'An isolated double bond with no adjacent lone pair or charge', ['An allylic carbocation', 'An allylic lone pair', 'Conjugated π bonds in a ring'], 'Without a lone pair, positive charge or conjugated π system next to it, a double bond cannot delocalize.')
    b.mc('2.10', 2, 'Which anion has an allylic lone pair and can therefore be drawn with resonance?', 'C=C[CH2-]', ['CCC[CH2-]', 'C=CCC[CH2-]', 'CCCC'], 'The lone pair on carbon is adjacent to the C=C π bond.', oimg=True)
    b.mc('2.10', 2, 'How many resonance structures (including the one drawn) are there for the allyl cation, CH₂=CH-CH₂⁺?', '2', ['1', '3', '4'], 'Moving the π bond swaps the positions of the double bond and the positive charge.', img=S('C=C[CH2+]'))
    b.mc('2.10', 2, 'How many resonance structures with alternating double bonds can be drawn for benzene?', '2', ['1', '3', '6'], 'Two Kekulé structures differ in the placement of the three double bonds.', img=S('C1=CC=CC=C1'))
    b.mc('2.10', 3, 'Which resonance pattern applies to acetate?', 'An allylic lone pair (a lone pair next to a π bond)', ['An allylic carbocation', 'A lone pair adjacent to a carbocation', 'Conjugated π bonds in a ring'], 'The lone pair on O⁻ is adjacent to the C=O π bond.', img=S('CC(=O)[O-]'))
    b.fr('2.10', 2, 'Draw both resonance structures of the allyl anion.', 'CH₂=CH-CH₂⁻ ↔ ⁻CH₂-CH=CH₂ (the two forms are equivalent).', 'Pattern 1: an allylic lone pair; one curved arrow from the lone pair and one from the π bond.', aimg=S('C=C[CH2-]', '@↔', '[CH2-]C=C'))
    b.fr('2.10', 2, 'Draw the second resonance structure of the allyl cation.', 'CH₂=CH-CH₂⁺ ↔ ⁺CH₂-CH=CH₂', 'Pattern 2: an allylic carbocation; the π bond shifts toward the positive carbon.', img=S('C=C[CH2+]'), aimg=S('C=C[CH2+]', '@↔', '[CH2+]C=C'))
    b.fr('2.10', 3, 'Draw a resonance structure of acrolein, CH₂=CH-CH=O, in which oxygen carries a negative charge.', '⁺CH₂-CH=CH-O⁻', 'Pattern 4 (a π bond between atoms of different electronegativity) combined with conjugation: the π electrons move onto oxygen.', img=S('C=CC=O'), aimg=S('C=CC=O', '@↔', '[CH2+]C=C[O-]'))
    b.fr('2.10', 3, 'Draw the resonance structure of CH₃-O-CH₂⁺ that places the positive charge on oxygen. Which pattern is this?', 'CH₃-O⁺=CH₂; pattern 3, a lone pair adjacent to a carbocation.', 'The oxygen lone pair forms a π bond to the carbon.', img=S('CO[CH2+]'), aimg=S('CO[CH2+]', '@↔', 'C[O+]=C'))
    b.fr('2.10', 4, 'How many resonance structures can be drawn for the phenoxide ion (including both Kekulé forms)? On which atoms can the negative charge be placed?', 'Five structures: the negative charge can be on the oxygen, on either ortho carbon, or on the para carbon; the oxygen form can be drawn with either Kekulé arrangement.',
         'The oxygen lone pair is adjacent to the ring π system, so charge moves to the ortho and para positions (not meta).', img=S('[O-]c1ccccc1'))
    # ------------------------------------------------------------ 2.11 Assessing the relative importance of resonance structures
    b.mc('2.11', 1, 'Which resonance structures contribute equally to the resonance hybrid?', 'Structures that are equally good Lewis structures (equivalent)', ['Structures with the most charges', 'Structures with the fewest filled octets', 'The first structure drawn'], 'Equivalent resonance forms have identical charge placement and bonding patterns.')
    b.mc('2.11', 2, 'Which resonance structure is the more significant contributor?', 'I, because the negative charge is on the more electronegative atom (oxygen)', ['II, because the negative charge is on carbon', 'They contribute equally', 'II, because it has fewer formal charges'],
         'Other things being equal, a negative charge is better on oxygen than on carbon.', img=S('C=C[O-]', '[CH2-]C=O', labels='I II'))
    b.mc('2.11', 2, 'Are the two resonance structures of acetate equivalent?', 'Yes, both have a negative charge on one oxygen and a C=O on the other', ['No, one has a negative charge on carbon', 'No, one has no formal charge', 'No, one has an incomplete octet'], 'Each oxygen carries the charge in one structure and the double bond in the other.', img=S('CC(=O)[O-]', 'CC([O-])=O', labels='I II'))
    b.mc('2.11', 3, 'Which resonance structure of the methoxymethyl cation is more significant?', 'II, because every atom has a complete octet', ['I, because the positive charge is on carbon', 'I, because it has fewer bonds', 'They are equivalent'], 'The carbon in structure I has only six electrons; in II all atoms have octets (the first rule).', img=S('CO[CH2+]', 'C[O+]=C', labels='I II'))
    b.fr('2.11', 2, 'State the first and second rules used to decide which resonance structure is more significant.', 'First, the structure with the greatest number of filled octets is more significant. Second, the structure with fewer formal charges is more significant.', 'These are two of the four rules in Section 2.11.')
    b.fr('2.11', 2, 'Why is a resonance structure with separated positive and negative charges usually less significant than one without charges?', 'Charge separation costs energy, and structures with fewer formal charges are more significant.', 'Rule 2: fewer formal charges.')
    b.fr('2.11', 3, 'Of the two resonance structures of the enolate shown, which contributes more to the hybrid and why?', 'The one with the negative charge on oxygen (I), because oxygen is more electronegative than carbon.', 'A negative charge is more stable on the more electronegative atom.', img=S('C=C[O-]', '[CH2-]C=O', labels='I II'))
    b.fr('2.11', 3, 'List the four guidelines for judging the significance of resonance structures.', '(1) Most filled octets; (2) fewest formal charges; (3) negative charge on the more electronegative atom (positive on the less); (4) equally good structures contribute equally.', 'These are the rules in Section 2.11.')
    # ------------------------------------------------------------ 2.12 The resonance hybrid
    b.mc('2.12', 2, 'How is a resonance hybrid drawn?', 'With dashed (partial) bonds and partial charges (δ)', ['With two structures and an equilibrium arrow', 'With the most stable structure only', 'With a double bond on each side'], 'Partial bonds and partial charges show the delocalization.')
    b.mc('2.12', 2, 'What is the carbon-oxygen bond order in each C-O bond of acetate?', '1.5', ['1', '2', '1 and 2 alternating'], 'The two oxygens are equivalent: each C-O bond is between a single and a double bond.', img=S('CC(=O)[O-]'))
    b.fr('2.12', 2, 'Describe how the resonance hybrid of the allyl cation is drawn.', 'Both carbon-carbon bonds are drawn as dashed partial double bonds, and each terminal carbon carries a partial positive charge (δ+).', 'The positive charge is shared equally by the two terminal carbons.', img=S('C=C[CH2+]'))
    b.fr('2.12', 2, 'In the resonance hybrid of acetate, what is the charge on each oxygen?', 'Each oxygen carries half of the negative charge (about -1/2, written δ⁻).', 'The one negative charge is shared by two equivalent oxygens.', img=S('CC(=O)[O-]'))
    # ------------------------------------------------------------ 2.13 Delocalized and localized lone pairs
    b.mc('2.13', 2, 'In an amide, the lone pair on nitrogen is:', 'Delocalized, because it is adjacent to the C=O π bond', ['Localized, because nitrogen is electronegative', 'Delocalized, because it is in an s orbital', 'Not present'], 'A lone pair next to a π bond can participate in resonance and occupies a p orbital.', img=S('CC(=O)N'))
    b.mc('2.13', 3, 'Compare the nitrogen lone pair in CH₃CH₂NH₂ and in CH₂=CHNH₂.', 'Localized in the first and delocalized in the second', ['Delocalized in both', 'Localized in both', 'Delocalized in the first and localized in the second'], 'Only the vinyl amine has a lone pair adjacent to a π bond.', img=S('CCN', 'C=CN', labels='I II'))
    b.mc('2.13', 3, 'A carbonyl oxygen has a π bond and lone pairs. Which statement is correct?', 'The π bond can participate in resonance but the lone pairs on that oxygen do not', ['The lone pairs and the π bond both participate in resonance', 'Neither the lone pairs nor the π bond can participate', 'The lone pairs participate but the π bond does not'], 'An atom with both a π bond and a lone pair uses only one of them in resonance (the π bond).', img=S('CC(=O)C'))
    b.fr('2.13', 2, 'In the ester shown, identify the oxygen lone pair that is delocalized and say why.', 'The lone pair on the single-bonded oxygen is delocalized because it is adjacent to the C=O π bond.', 'The carbonyl oxygen lone pairs are localized (in sp² orbitals).', img=S('CC(=O)OC'))
    b.fr('2.13', 3, 'Is the nitrogen lone pair in aniline localized or delocalized? Explain.', 'Delocalized: it is adjacent to the π system of the ring, so it participates in resonance.', 'The lone pair occupies a p orbital that overlaps with the ring π bonds.', img=S('Nc1ccccc1'))
    b.fr('2.13', 3, 'Draw the resonance structure of the amide shown that results from delocalizing the nitrogen lone pair.', 'CH₃C(O⁻)=NH₂⁺: the nitrogen lone pair forms a C=N π bond and the C=O π electrons move onto oxygen.', 'This is pattern 1 combined with the polarized C=O.', img=S('CC(=O)N'), aimg=S('CC(=O)N', '@↔', 'CC([O-])=[NH2+]'))
